import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.for-each.js";
/*eslint-disable*/
import { format_Date } from "@/JsonFiles/DateFormate.js";
import SnackBar from "@/components/SnackBar.vue";
import ExportPartipatedDialog from "@/components/Approvals/ExportParctipatedDialog.vue";
import { list_participants_workflows_v1, all_users_of_organization } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import FormInfo from "@/components/FormFields/FormInfo.vue";
import OverlayComp from "@/components/OverlayComp.vue";
import { get_workflow_payload } from "@/mixins/GetWorkflowDetails.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { get_workflows } from "@/mixins/GetWorkflowsummary.js";
import CreateTicketDialog from "../Tickets/CreateTicketDialog.vue";
import html2canvas from "html2canvas";
export default {
  components: {
    SnackBar,
    FormInfo,
    OverlayComp,
    CreateTicketDialog,
    ExportPartipatedDialog
  },
  mixins: [get_workflow_payload, get_all_org_users, get_workflows],
  data() {
    return {
      ExportDialog: false,
      SnackBarComponent: {},
      userselect: "",
      userArray: [],
      searchuser: "",
      tableData: [],
      height: 0,
      tableLoading: false,
      next_token: null,
      fixed: true,
      headers: [{
        title: "Transaction ID / Workflow Name",
        key: "transaction_id",
        sortable: false
      }, {
        title: "Initiated By",
        key: "workflow_initiated_name",
        sortable: false
      }, {
        title: "Summary Fields",
        key: "summary_field_1",
        sortable: false
      }, {
        title: "Last Acted By",
        key: "workflow_approval_name",
        sortable: false
      }, {
        title: "Pending On",
        key: "pending_on",
        sortable: false
      }, {
        title: "Initiated On / Acted On",
        key: "workflow_initiated_on",
        sortable: false
      }, {
        title: "Status",
        key: "approval_status",
        sortable: false,
        width: "100px"
      }],
      submittedInfo: false,
      formDetails: {},
      formAction: "",
      componentCheck: 0,
      overlay: false,
      filterByAction: "",
      filterBy: "ALL",
      goLoading: false,
      workflowItems: [],
      search: "",
      workflowCheck: false,
      allUSersNames: [],
      selectItems: [],
      summarylabel: "",
      searchsummary: "",
      rowInfo: {},
      isVisible: false,
      // Pagination properties
      currentPage: 1,
      itemsPerPage: 20,
      totalItems: 0,
      windowHeight: 0,
      // Filter drawer properties
      showFilterDrawer: false,
      //Screenshot Values
      DialogCreateTicket: false,
      ScreenshotFile: null,
      orgDetails: {
        bucket_name: "stichh-medias",
        region: "us-east-1"
      }
    };
  },
  computed: {
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    activeFiltersCount() {
      let count = 0;

      // Count status filter (if not default)
      if (this.filterBy && this.filterBy !== "ALL") {
        count++;
      }

      // Count user search
      if (this.userselect && this.userselect !== "") {
        count++;
      }

      // Count workflow filter
      if (this.filterByAction && this.filterByAction !== "") {
        count++;
      }

      // Count summary field filter
      if (this.summarylabel && this.summarylabel !== "") {
        count++;
      }

      // Count search summary
      if (this.searchsummary && this.searchsummary !== "") {
        count++;
      }
      return count;
    }
  },
  watch: {
    filterByAction(newVal) {
      const selectedWorkflow = this.summaryOrgWorkflows.find(item => item.workflow_name === newVal);
      if (selectedWorkflow) {
        this.selectItems = [];
        if (selectedWorkflow.summary_field_1) {
          this.selectItems.push({
            text: selectedWorkflow.summary_field_1.replace(/_/g, " "),
            value: "summary_field_1"
          });
        }
        if (selectedWorkflow.summary_field_2) {
          this.selectItems.push({
            text: selectedWorkflow.summary_field_2.replace(/_/g, " "),
            value: "summary_field_2"
          });
        }
      }
    },
    currentPage(newVal, oldVal) {
      // When the page changes, check if we need to load more data
      if (newVal > oldVal && this.next_token) {
        // User is going to next page and we have more data to load
        this.get_participated_workflow();
      } else {
        // Just scroll to top of table for same page or going back
        const table = document.querySelector(".modern-data-table");
        if (table) table.scrollIntoView({
          behavior: "smooth",
          block: "start"
        });
      }
    }
  },
  async created() {
    this.isVisible = true;
    this.height = window.innerHeight - 220;
    await Promise.all([this.get_participated_workflow(), this.get_all_org_users(), this.get_workflows()]);
    this.allUSersNames = this.orgUsers;
    this.$store.commit("Setnamesearch", "");
    this.fetch_all_workflows();
  },
  methods: {
    refresh_list() {
      this.next_token = null;
      this.get_participated_workflow();
      ;
    },
    exportClick() {
      this.ExportDialog = true;
    },
    async TakeScreenshot() {
      const target = document.body;
      const canvas = await html2canvas(target, {
        scale: window.devicePixelRatio || 2,
        useCORS: true,
        logging: false,
        windowWidth: document.documentElement.scrollWidth,
        windowHeight: document.documentElement.scrollHeight
      });
      const dataUrl = canvas.toDataURL("image/png");
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], "screenshot.png", {
        type: "image/png"
      });
      this.ScreenshotFile = file;
      this.DialogCreateTicket = true;
    },
    DialogCreateTicketEmit() {
      this.DialogCreateTicket = false;
    },
    // Filter drawer methods
    openFilterDrawer() {
      this.showFilterDrawer = true;
    },
    closeFilterDrawer() {
      this.showFilterDrawer = false;
    },
    applyFilterFromDrawer() {
      // Apply the filter and close the drawer
      this.filter_data();
      this.closeFilterDrawer();
    },
    getStatusColor(status) {
      switch (status) {
        case "COMPLETED":
          return "success";
        case "INPROGRESS":
          return "warning";
        case "REJECTED":
          return "error";
        case "WITHDRAWN":
          return "primary";
        default:
          return "grey";
      }
    },
    getStatusIcon(status) {
      switch (status) {
        case "COMPLETED":
          return "mdi-check-circle";
        case "INPROGRESS":
          return "mdi-clock-outline";
        case "REJECTED":
          return "mdi-close-circle";
        case "WITHDRAWN":
          return "mdi-account-remove";
        default:
          return "mdi-help-circle";
      }
    },
    back_call() {
      this.$router.push("/home/DashboardView");
    },
    getFileName(url) {
      if (typeof url === "string") {
        const match = url.match(/[^\/]+\.(jpg|png|xlsx|jpeg|gif|bmp|tiff|pdf|doc|docx|xls|csv|txt|mp4|mp3|avi|mkv)$/i);
        return match ? match[0] : url;
      } else {
        return url;
      }
    },
    clear_data() {
      this.filterBy = "ALL";
      this.userselect = "";
      this.filterByAction = "";
      this.summarylabel = "";
      this.selectItems = [];
      this.tableData = [];
      this.next_token = null;
      this.currentPage = 1;
      this.totalItems = 0;
      this.get_participated_workflow();
    },
    get_participatedworkflow_Pagination() {
      if (this.next_token) {
        this.get_participated_workflow();
      }
    },
    fetch_user_name(value) {
      var name = "";
      this.allUSersNames.forEach(element => {
        if (element.user_email_id == value) {
          name = element.full_user_name;
        }
      });
      if (value == "SYSTEM") {
        name = value;
      }
      return name;
    },
    input_check() {
      if (this.filterByAction != "") {
        this.workflowCheck = true;
        this.summarylabel = "";
        this.searchsummary = "";
      }
    },
    filter_data() {
      if (this.summarylabel != "" && this.searchsummary == "") {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Search by summary with a minimum of three characters",
          timeout: 5000,
          Top: true
        };
      } else {
        this.tableData = [];
        this.goLoading = true;
        this.next_token = null;
        this.currentPage = 1;
        this.totalItems = 0;
        this.get_participated_workflow();
      }
    },
    fetch_all_workflows() {
      this.workflowItems = [];
      this.summaryOrgWorkflows.forEach(element => {
        this.workflowItems.push(element.workflow_name);
      });
      this.workflowItems.sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()));
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userArray.push({
            full_user_name: element.full_user_name,
            user_id: element.user_email_id
          });
        }
      });
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.submittedInfo = false;
      this.tableData = [];
      this.next_token = null;
      this.currentPage = 1;
      this.totalItems = 0;
      this.ExportDialog = false;
      await this.get_participated_workflow();
    },
    fetch_value(val) {
      if (val == undefined) {
        return "-";
      } else {
        return format_Date(val);
      }
    },
    async handleClick(click, value) {
      this.overlay = true;
      var initaorName = this.fetch_user_name(value.item.workflow_initiated_name);
      localStorage.setItem("initiatedBy", initaorName);
      this.rowInfo = value.item;
      this.$store.commit("SetInitiatorId", value.item.initiate_id);
      await this.get_workflow_payload();
      this.overlay = false;
      this.componentCheck = 1;
      this.submittedInfo = true;
      this.formDetails = this.workflowInfoPaylod;
      this.formAction = "Submited";
    },
    async get_participated_workflow() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_participants_workflows_v1, {
          input: {
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            limit: 21,
            nextToken: this.next_token,
            approval_status: this.filterBy,
            workflow_name: this.filterByAction == null ? "" : this.filterByAction,
            workflow_initiated_by: this.userselect == null ? "" : this.userselect,
            summary_field_1: this.summarylabel == "summary_field_1" ? this.searchsummary.trim().length == 0 ? undefined : this.searchsummary : undefined,
            summary_field_2: this.summarylabel == "summary_field_2" ? this.searchsummary.trim().length == 0 ? undefined : this.searchsummary : undefined
          }
        }));
        this.tableLoading = false;
        this.goLoading = false;
        var response = JSON.parse(result.data.list_participants_workflows_v1);
        this.next_token = response.nextToken;
        if (response.Status == "SUCCESS") {
          this.goLoading = false;
          if (this.next_token) {
            // If we have more data, concatenate to existing array
            let array = this.tableData.concat(response.workflow);
            this.tableData = array;
          } else {
            // If no more data, concatenate what we have (don't replace)
            if (response.workflow && response.workflow.length > 0) {
              let array = this.tableData.concat(response.workflow);
              this.tableData = array;
            }
          }
          const uniqueArrayOfObjects = this.tableData.filter((obj, index, self) => index === self.findIndex(o => o.participant_id === obj.participant_id));
          this.tableData = uniqueArrayOfObjects;
          for (let i = 0; i < this.tableData.length; i++) {
            this.tableData[i].pending_on = this.tableData[i].workflow_approval_name;
          }

          // Update total items for pagination
          this.totalItems = this.tableData.length;
        } else {
          this.goLoading = false;
          // Only clear data if this is the first load (no next_token) or filter reset
          if (!this.next_token && this.tableData.length === 0) {
            this.tableData = [];
            this.totalItems = 0;
          }
        }
      } catch (error) {
        this.tableLoading = false;
        this.goLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
